{
  "name": "可编程交流电源",
  "name_en": "Programmable AC Power Source",
  "manufacturer": "",
  "description": "用于实验室中输出并调节交流电的电源设备，可设置电压、频率、电流限制以及输出开关，常用于供电测试、交流输入模拟和电源设备验证。",
  "description_en": "A laboratory AC power source used to generate and control AC output. It supports setting voltage, frequency, current limit, and output on/off, and is commonly used for power input simulation, supply testing, and validation of AC-powered equipment.",
  "actions": [
    {
      "action_name": "auto-volts",
      "description": "读取或设置交流输出电压。",
      "description_en": "Get or set the AC output voltage."
    },
    {
      "action_name": "auto-frequency",
      "description": "读取或设置交流输出频率。",
      "description_en": "Get or set the AC output frequency."
    },
    {
      "action_name": "auto-output",
      "description": "读取或设置交流输出开关状态。",
      "description_en": "Get or set the AC output enable state."
    },
    {
      "action_name": "auto-current",
      "description": "读取或设置输出电流参数。",
      "description_en": "Get or set the output current parameter."
    }
  ],
  "tag_hints": [
    "AC power source",
    "programmable AC output",
    "voltage control",
    "frequency control",
    "current setting",
    "power supply testing",
    "line input simulation"
  ]
}

